WITH source AS MATERIALIZED (SELECT * FROM jsonb_to_recordset($1::jsonb) AS value(id_user integer,points integer,rank integer)), changed AS MATERIALIZED (SELECT target.id_user,target.rank AS previous_rank,source.rank FROM public.user_points target JOIN source USING(id_user) WHERE target.rank IS DISTINCT FROM source.rank), updated AS (UPDATE public.user_points target SET rank=changed.rank,date_updated=clock_timestamp() FROM changed WHERE target.id_user=changed.id_user RETURNING target.id_user) SELECT changed.id_user,changed.previous_rank,changed.rank FROM changed JOIN updated USING(id_user) ORDER BY changed.rank,changed.id_user
